import { Formik, Form, Field, ErrorMessage } from "formik";

<Formik
  initialValues={{ email: "" }}
  onSubmit={(values) => console.log(values)}
  validate={(values) => {
    const errors: any = {};
    if (!values.email) errors.email = "Required";
    return errors;
  }}
>
  <Form>
    <Field name="email" type="email" />
    <ErrorMessage name="email" />
  </Form>
</Formik>
